import json
import unicodedata


def transform_jsonl(text: str) -> str:
    """
    Normalize JSON Lines records as described in the acceptance task.
    """
    lines = text.splitlines(keepends=True)
    output_lines = []

    for i, line in enumerate(lines, 1):
        line = line.strip()
        if not line:
            continue

        try:
            obj = json.loads(line)
        except json.JSONDecodeError as e:
            raise ValueError(f"Malformed JSON at line {i}") from e

        if not isinstance(obj, dict):
            raise ValueError(f"Invalid object at line {i}")

        name = obj.get('name')
        tags = obj.get('tags', [])

        if not isinstance(name, str) or not name:
            raise ValueError(f"Missing or invalid name at line {i}")

        normalized_name = unicodedata.normalize('NFC', name).strip()
        if not normalized_name:
            raise ValueError(f"Empty normalized name at line {i}")

        normalized_tags = []
        if not isinstance(tags, list):
            raise ValueError(f"tags must be a list at line {i}")
        for tag in tags:
            if not isinstance(tag, str):
                raise ValueError(f"tag must be a string at line {i}")
            normalized_tag = unicodedata.normalize('NFC', tag).strip()
            if normalized_tag:
                if not normalized_tag in normalized_tags:
                    normalized_tags.append(normalized_tag)

        # Create new object with normalized fields
        new_obj = obj.copy()
        new_obj['name'] = normalized_name
        new_obj['tags'] = normalized_tags

        # Sort keys and emit compact JSON
        sorted_keys = sorted(new_obj.keys())
        compact_json = json.dumps({k: new_obj[k] for k in sorted_keys}, separators=(',', ':'))
        output_lines.append(compact_json + '\n')

    return ''.join(output_lines)

